const t = $input.all()[0].json;
const lastCustomerReply = t.lastCustomerReplyAt ? new Date(t.lastCustomerReplyAt) : null;
const resolvedAt = new Date(t.resolvedAt || t.updatedAt);
const now = new Date();
const daysSinceResolved = (now - resolvedAt) / 86400000;
const daysSinceCustomerReply = lastCustomerReply ? (now - lastCustomerReply) / 86400000 : 999;
// Auto-close if: resolved for 7+ days AND no customer response in that window
const shouldClose = daysSinceResolved >= 7 && daysSinceCustomerReply >= 7;
return [{
  json: {
    shouldClose,
    daysSinceResolved: daysSinceResolved.toFixed(1),
    daysSinceCustomerReply: daysSinceCustomerReply === 999 ? null : daysSinceCustomerReply.toFixed(1),
    ticketId: t.id,
    ticketNumber: t.ticketNumber || t.id,
    subject: t.subject,
    customerId: t.customerId,
    customerEmail: t.customerEmail,
    tenantId: t.tenantId,
    assigneeId: t.assigneeId,
    resolvedAt: t.resolvedAt || t.updatedAt
  }
}];

